using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Xunit;

namespace RA.Utilities.Tests.Generators;

/// <summary>
/// Verifies the shape of the source generated by the mediator implementation generator:
/// monomorphic per-message overloads, explicit interface implementations, the if-chain versus
/// fast-dictionary dispatch switch, and the message/handler diagnostics (FEAG006-FEAG009).
/// </summary>
public class MediatorImplementationGeneratorTests
{
    private const string GeneratedHintName = "RA.Utilities.Feature.MediatorImpl.g.cs";

    private const string BasicMessages = """
        using System.Threading;
        using System.Threading.Tasks;

        namespace Sample
        {
            public record Ping(string Value) : global::RA.Utilities.Feature.Abstractions.IRequest<Pong>;

            public record Pong(string Value);

            public class PingHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<Ping, Pong>
            {
                public Task<Pong> HandleAsync(Ping request, CancellationToken cancellationToken) => Task.FromResult(new Pong(request.Value));
            }

            public record DoNothing : global::RA.Utilities.Feature.Abstractions.IRequest;

            public class DoNothingHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<DoNothing>
            {
                public Task HandleAsync(DoNothing request, CancellationToken cancellationToken) => Task.CompletedTask;
            }

            public record OrderPlaced(string OrderId) : global::RA.Utilities.Feature.Abstractions.INotification;

            public class OrderPlacedHandler : global::RA.Utilities.Feature.Abstractions.INotificationHandler<OrderPlaced>
            {
                public Task HandleAsync(OrderPlaced notification, CancellationToken cancellationToken) => Task.CompletedTask;
            }
        }
        """;

    [Fact]
    public void EmitsMonomorphicOverloads_ForEveryMessageKind()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("public global::System.Threading.Tasks.Task<global::Sample.Pong> Send(global::Sample.Ping request");
        generated.Should().Contain("public global::System.Threading.Tasks.Task<global::Sample.Pong> Send<TContext>(global::Sample.Ping request");
        generated.Should().Contain("public global::System.Threading.Tasks.Task Send(global::Sample.DoNothing request");
        generated.Should().Contain("public global::System.Threading.Tasks.Task Send<TContext>(global::Sample.DoNothing request");
        generated.Should().Contain("public async global::System.Threading.Tasks.Task Publish(global::Sample.OrderPlaced notification");
        generated.Should().Contain("public async global::System.Threading.Tasks.Task Publish<TContext>(global::Sample.OrderPlaced notification");
        generated.Should().Contain("public global::System.Threading.Tasks.Task<object?> Send(object request");
        generated.Should().Contain("public global::System.Threading.Tasks.Task Publish(object notification");
    }

    [Fact]
    public void MediatorImpl_IsStandalone_AndImplementsTheInterface()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("internal sealed class MediatorImpl : global::RA.Utilities.Feature.Abstractions.IMediator");
        generated.Should().Contain("public MediatorImpl(global::System.IServiceProvider provider, global::Microsoft.Extensions.Logging.ILogger<MediatorImpl> logger)");
        generated.Should().Contain("global::System.Threading.Tasks.Task global::RA.Utilities.Feature.Abstractions.IMediator.Send<TRequest>(TRequest request");
        generated.Should().Contain("global::System.Threading.Tasks.Task<TResponse> global::RA.Utilities.Feature.Abstractions.IMediator.Send<TRequest, TResponse>(TRequest request");
        generated.Should().Contain("global::System.Threading.Tasks.Task global::RA.Utilities.Feature.Abstractions.IMediator.Publish<TNotification>(TNotification notification");
        generated.Should().NotContain(": global::RA.Utilities.Feature.Mediator");
    }

    [Fact]
    public void EmitsRegistrationInitializer_WhenNotDisabled()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("internal static class MediatorRegistrationInitializer");
        generated.Should().Contain("global::RA.Utilities.Feature.Generated.MediatorRegistrations.Add(static services =>");
        generated.Should().Contain("AddScoped<MediatorImpl>(services)");
    }

    [Fact]
    public void SmallProject_UsesTypeChains_ForObjectDispatch_InsteadOfDictionaries()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("if (requestType == typeof(global::Sample.Ping))");
        generated.Should().Contain("if (requestType == typeof(global::Sample.DoNothing))");
        generated.Should().Contain("if (notificationType == typeof(global::Sample.OrderPlaced))");
        generated.Should().NotContain("s_sendObject");
        generated.Should().NotContain("s_publish");
    }

    [Fact]
    public void LargeProject_UsesFastDictionaries_ForObjectDispatch()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BuildManyMessagesSource(17)]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("private static readonly global::System.Collections.Generic.Dictionary<global::System.Type, global::System.Func<MediatorImpl, object, global::System.Threading.CancellationToken, global::System.Threading.Tasks.Task<object?>>> s_sendObject");
        generated.Should().Contain("private static readonly global::System.Collections.Generic.Dictionary<global::System.Type, global::System.Func<MediatorImpl, object, global::System.Threading.CancellationToken, global::System.Threading.Tasks.Task>> s_publish");
        generated.Should().Contain("[typeof(global::Sample.Request0)] = static (impl, request, cancellationToken) =>");
        generated.Should().Contain("s_sendObject.TryGetValue(requestType");
        generated.Should().Contain("s_publish.TryGetValue(notificationType");
    }

    [Fact]
    public void ValueTypeResponse_UsesBoxingHelper_ForObjectDispatch()
    {
        const string sources = """
            using System.Threading;
            using System.Threading.Tasks;

            namespace Sample
            {
                public record CountRequest : global::RA.Utilities.Feature.Abstractions.IRequest<int>;

                public class CountHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<CountRequest, int>
                {
                    public Task<int> HandleAsync(CountRequest request, CancellationToken cancellationToken) => Task.FromResult(42);
                }
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("return BoxAsync(task);");
        generated.Should().Contain("private static async global::System.Threading.Tasks.Task<object?> BoxAsync<T>(global::System.Threading.Tasks.Task<T> task)");
    }

    [Fact]
    public void ReferenceTypeResponse_UsesUnsafeCast_ForObjectDispatch()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("return global::System.Runtime.CompilerServices.Unsafe.As<global::System.Threading.Tasks.Task<global::Sample.Pong>, global::System.Threading.Tasks.Task<object?>>(ref task);");
    }

    [Fact]
    public void StructMessage_EmitsOverload_WithoutNullCheck()
    {
        const string sources = """
            using System.Threading;
            using System.Threading.Tasks;

            namespace Sample
            {
                public struct StructRequest : global::RA.Utilities.Feature.Abstractions.IRequest<int>;

                public class StructHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<StructRequest, int>
                {
                    public Task<int> HandleAsync(StructRequest request, CancellationToken cancellationToken) => Task.FromResult(7);
                }
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("public global::System.Threading.Tasks.Task<int> Send(global::Sample.StructRequest request");

        // Struct messages need no null check: the mono overload goes straight to the concrete
        // handler resolution and the direct call (the unrelated Send(object) overload keeps its
        // own object null check).
        generated.Should().Contain("""
            public global::System.Threading.Tasks.Task<int> Send(global::Sample.StructRequest request, global::System.Threading.CancellationToken cancellationToken = default)
                    {
                        global::Sample.StructHandler handler =
            """);
        generated.Should().Contain("return handler.HandleAsync(request, cancellationToken);");
    }

    [Fact]
    public void DualResponseContracts_ReportFEAG006_AndExcludeTheMessage()
    {
        const string sources = """
            namespace Sample
            {
                public record Dual : global::RA.Utilities.Feature.Abstractions.IRequest<string>, global::RA.Utilities.Feature.Abstractions.IRequest<int>;
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        Diagnostic diagnostic = GetDiagnostics(runResult).Should().ContainSingle().Which;
        diagnostic.Id.Should().Be("FEAG006");
        diagnostic.Severity.Should().Be(DiagnosticSeverity.Error);
        diagnostic.GetMessage().Should().Contain("Dual");

        // A compilation whose only message is ambiguous emits no mediator at all.
        runResult.Results.SelectMany(static result => result.GeneratedSources).Should().BeEmpty();
    }

    [Fact]
    public void RequestAndNotificationContract_ReportsFEAG006()
    {
        const string sources = """
            namespace Sample
            {
                public record Mixed : global::RA.Utilities.Feature.Abstractions.IRequest<string>, global::RA.Utilities.Feature.Abstractions.INotification;
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        Diagnostic diagnostic = GetDiagnostics(runResult).Should().ContainSingle().Which;
        diagnostic.Id.Should().Be("FEAG006");
        diagnostic.Severity.Should().Be(DiagnosticSeverity.Error);
    }

    [Fact]
    public void RedundantVoidAndResponseContract_IsTreatedAsResponseRequest_WithoutDiagnostic()
    {
        const string sources = """
            using System.Threading;
            using System.Threading.Tasks;

            namespace Sample
            {
                public record Redundant : global::RA.Utilities.Feature.Abstractions.IRequest, global::RA.Utilities.Feature.Abstractions.IRequest<string>;

                public class RedundantHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<Redundant, string>
                {
                    public Task<string> HandleAsync(Redundant request, CancellationToken cancellationToken) => Task.FromResult("ok");
                }
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        GetDiagnostics(runResult).Should().BeEmpty();

        string generated = GetGeneratedSource(runResult);
        generated.Should().Contain("public global::System.Threading.Tasks.Task<string> Send(global::Sample.Redundant request");
        generated.Should().NotContain("public global::System.Threading.Tasks.Task Send(global::Sample.Redundant request");
    }

    [Fact]
    public void RequestWithoutHandler_ReportsFEAG007()
    {
        const string sources = """
            namespace Sample
            {
                public record OrphanRequest : global::RA.Utilities.Feature.Abstractions.IRequest<string>;
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        Diagnostic diagnostic = GetDiagnostics(runResult).Should().ContainSingle().Which;
        diagnostic.Id.Should().Be("FEAG007");
        diagnostic.Severity.Should().Be(DiagnosticSeverity.Warning);
