    [Fact]
    public void RequestWithHandler_ReportsNoFEAG007()
    {
        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        GetDiagnostics(runResult).Should().BeEmpty();
    }

