    [Fact]
    public void HandlerWithBothContracts_ReportsFEAG009()
    {
        const string sources = """
            using System.Threading;
            using System.Threading.Tasks;

            namespace Sample
            {
                public record DualContractRequest : global::RA.Utilities.Feature.Abstractions.IRequest, global::RA.Utilities.Feature.Abstractions.IRequest<int>;

                public class DualContractHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<DualContractRequest>, global::RA.Utilities.Feature.Abstractions.IRequestHandler<DualContractRequest, int>
                {
                    public Task HandleAsync(DualContractRequest request, CancellationToken cancellationToken) => Task.CompletedTask;

                    public Task<int> HandleAsync(DualContractRequest request, CancellationToken cancellationToken) => Task.FromResult(1);
                }
            }
            """;

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([sources]);

        Diagnostic diagnostic = GetDiagnostics(runResult).Should().ContainSingle().Which;
        diagnostic.Id.Should().Be("FEAG009");
        diagnostic.Severity.Should().Be(DiagnosticSeverity.Warning);
        diagnostic.GetMessage().Should().Contain("DualContractHandler");
    }

    [Fact]
    public void SeamDefine_EmitsMediatorImpl_WithoutRegistrationInitializer()
    {
        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest)
            .WithPreprocessorSymbols(GeneratorTestHost.DisableModuleInitializerDefine);

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator([BasicMessages], parseOptions);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("internal sealed class MediatorImpl");
        generated.Should().NotContain("MediatorRegistrationInitializer");
    }

    [Fact]
    public void NoRuntimeContracts_EmitsNothing()
    {
        (Compilation _, GeneratorDriverRunResult runResult) =
            GeneratorTestHost.RunMediatorGenerator([""], includeRealRuntime: false);

        runResult.Results.SelectMany(static result => result.GeneratedSources).Should().BeEmpty();
    }

    [Fact]
    public void ReferencedAssemblyMessages_AreIncluded_WhenAccessible()
    {
        const string librarySources = """
            using System.Threading;
            using System.Threading.Tasks;

            namespace Lib
            {
                public record LibRequest(string Value) : global::RA.Utilities.Feature.Abstractions.IRequest<string>;

                public class LibHandler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<LibRequest, string>
                {
                    public Task<string> HandleAsync(LibRequest request, CancellationToken cancellationToken) => Task.FromResult("ok");
                }

                internal record HiddenRequest : global::RA.Utilities.Feature.Abstractions.IRequest<string>;
            }
            """;

        MetadataReference library = GeneratorTestHost.CompileToReference([librarySources]);

        (_, GeneratorDriverRunResult runResult) = GeneratorTestHost.RunMediatorGenerator(
            ["namespace App { public class Entry { } }"],
            additionalReferences: [library]);

        string generated = GetGeneratedSource(runResult);

        generated.Should().Contain("public global::System.Threading.Tasks.Task<string> Send(global::Lib.LibRequest request");
        generated.Should().NotContain("HiddenRequest");
        GetDiagnostics(runResult).Should().BeEmpty();
    }

    [Fact]
    public void Emission_IsDeterministic_AcrossRuns()
    {
        (_, GeneratorDriverRunResult firstRun) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);
        (_, GeneratorDriverRunResult secondRun) = GeneratorTestHost.RunMediatorGenerator([BasicMessages]);

        GetGeneratedSource(firstRun).Should().Be(GetGeneratedSource(secondRun));
    }

    private static string GetGeneratedSource(GeneratorDriverRunResult runResult) =>
        runResult.Results
            .SelectMany(static result => result.GeneratedSources)
            .Single(static source => source.HintName == GeneratedHintName)
            .SourceText.ToString();

    private static ImmutableArray<Diagnostic> GetDiagnostics(GeneratorDriverRunResult runResult) =>
        runResult.Results.SelectMany(static result => result.Diagnostics).ToImmutableArray();

    private static string BuildManyMessagesSource(int count)
    {
        var builder = new StringBuilder();
        builder.AppendLine("using System.Threading;");
        builder.AppendLine("using System.Threading.Tasks;");
        builder.AppendLine("namespace Sample");
        builder.AppendLine("{");

        for (int i = 0; i < count; i++)
        {
            builder.AppendLine($"    public record Request{i} : global::RA.Utilities.Feature.Abstractions.IRequest<string>;");
            builder.AppendLine($"    public class Request{i}Handler : global::RA.Utilities.Feature.Abstractions.IRequestHandler<Request{i}, string>");
            builder.AppendLine("    {");
            builder.AppendLine($"        public Task<string> HandleAsync(Request{i} request, CancellationToken cancellationToken) => Task.FromResult(\"ok\");");
            builder.AppendLine("    }");
        }

        builder.AppendLine("}");
        return builder.ToString();
    }
}
